"""Reviewed spell -> effect definitions. Catalogue IDs are explicit, no text guessing."""
import copy
EFFECTS=[]
def rule(kind, **kw):return {'kind':kind,**kw}
def mode(value,scopes,abilities=None,**kw):return rule('roll_mode',mode=value,scopes=scopes,**({'ability_ids':abilities} if abilities else {}),**kw)
def defense(*types,kind='resistance'):return [{'damage_type':t,'kind':kind} for t in types]
def add(id,desc,rules=(),defenses=(),*,key='effect',name=None,condition='',duration=None,weapon=None,extra=None,note='',full=False,count=None,per_slot=0,self_only=False,bindings=None,duration_levels=None):
 EFFECTS.append(dict(spell=id,key=key,name=name,desc=desc,rules=list(rules),defenses=list(defenses),condition=condition,duration=duration,weapon=weapon,extra=extra or {},note=note,full=full,count=count,per_slot=per_slot,self_only=self_only,bindings=bindings or [],duration_levels=duration_levels or []))
checks=['ability_check','skill_check']
saves=['saving_throw']
add(544,'Защитное небесное явление сопровождает цель. КД +2. После провала спасброска Ловкости можно реакцией перебросить его и окончить эффект.',[rule('armor_bonus',value=2)],note='КД применяется. Перебросок реакцией и снятие эффекта после него — вручную.')
