add(1194,'Выбранное оружие наносит +2к8 излучением. Бонусным действием заклинание можно окончить вспышкой: 4к8 излучением и спасбросок Телосложения.',extra={'weapon_target':{}},weapon={'dice':'d8','dice_count':2,'damage_type':7},note=weapon_note+' Вспышка, её спасбросок и ослепление разрешаются отдельно.')
